== decisions/D-3avp7m-write-null-handling.json
{
  "contract_version": 2,
  "decision": {
    "id": "D-3avp7m",
    "slug": "write-null-handling",
    "title": "Explicit null on optional write arguments",
    "status": "resolved",
    "date": "2026-10-21",
    "phase": "design",
    "question": "When a caller passes null for an optional write argument (updateOrder note; createOrder payment and item unitPriceCents), should the connector omit the key or send JSON null?",
    "context": "Recommendation: omit. The spec does not say null clears a field, and every optional write member is nullable-by-omission only.",
    "affects": [
      "patch:/orders/{orderId}",
      "post:/orders"
    ],
    "choices": [
      {
        "id": "omit",
        "label": "Omit the key (selection default)"
      },
      {
        "id": "send-null",
        "label": "Send null (lets a caller clear updateOrder note)"
      }
    ],
    "resolution": {
      "chosen": [
        "omit"
      ],
      "note": "demo answer",
      "by": "user",
      "at": "2026-10-21"
    }
  }
}

== decisions/D-4yyj7v-customer-pii.json
{
  "contract_version": 2,
  "decision": {
    "id": "D-4yyj7v",
    "slug": "customer-pii",
    "title": "Customer personal data",
    "status": "resolved",
    "date": "2026-10-21",
    "phase": "design",
    "question": "Lumen_Books_Customer carries name, email and phone. How should the subgraph treat them?",
    "context": "Recommendation: hide-contact. Email and phone are personal data the spec flags; masking needs string handling in the mapping and is harder to test. Email is required in the source, so hiding it is a recorded omit.",
    "affects": [
      "Lumen_Books_Customer.email",
      "Lumen_Books_Customer.phone",
      "Lumen_Books_Customer.name"
    ],
    "choices": [
      {
        "id": "expose",
        "label": "Expose name, email and phone"
      },
      {
        "id": "hide-contact",
        "label": "Expose name, hide email and phone"
      },
      {
        "id": "hide-all",
        "label": "Hide name, email and phone (id, tier, createdAt only)"
      },
      {
        "id": "mask",
        "label": "Expose masked email and phone (e.g. j***@x.com, last digits of phone)"
      }
    ],
    "resolution": {
      "chosen": [
        "hide-contact"
      ],
      "note": "demo answer",
      "by": "user",
      "at": "2026-10-21"
    }
  }
}

