== decisions/D-oqs0jf-books-pagination.json
{
  "contract_version": 2,
  "decision": {
    "id": "D-oqs0jf",
    "slug": "books-pagination",
    "title": "Pagination for books",
    "status": "resolved",
    "date": "2026-10-21",
    "phase": "design",
    "question": "GET /books is page-number paged (page from 1, limit default 10, max 50) and returns meta {page, limit, total}. What should lumen_books_books expose?",
    "context": "Recommendation: wrapper. total is the stop signal the caller needs; the same type also serves searchBooks, which returns the same BookPage shape. The genre and ids filters are exposed either way.",
    "affects": [
      "get:/books",
      "post:/books/search"
    ],
    "choices": [
      {
        "id": "wrapper",
        "label": "page and limit arguments; return a page type with data and page/limit/total"
      },
      {
        "id": "flatten",
        "label": "page and limit arguments; return the list only (no total)"
      },
      {
        "id": "first-page",
        "label": "No paging arguments; return the first page only"
      }
    ],
    "resolution": {
      "chosen": [
        "wrapper"
      ],
      "note": "demo answer",
      "by": "user",
      "at": "2026-10-21"
    }
  }
}

== decisions/D-ox8zkp-relationship-links.json
{
  "contract_version": 2,
  "decision": {
    "id": "D-ox8zkp",
    "slug": "relationship-links",
    "title": "Relationship links",
    "status": "resolved",
    "date": "2026-10-21",
    "phase": "design",
    "question": "Which candidate links should become relationship fields? Each is one extra request per parent.",
    "context": "Recommendation: Book.author and OrderItem.book; drop Order.customer unless the customer data decision exposes it. OrderItem.book runs once per order item, so it is cheaper with batching. None of the three is circular or self-referencing.",
    "multiple": true,
    "affects": [
      "selection.yaml"
    ],
    "choices": [
      {
        "id": "book-author",
        "label": "Book.author (via GET /authors/{authorId})"
      },
      {
        "id": "order-customer",
        "label": "Order.customer (via GET /customers/{customerId})"
      },
      {
        "id": "orderitem-book",
        "label": "OrderItem.book (via GET /books/{bookId})"
      },
      {
        "id": "none",
        "label": "None: expose the ids only"
      }
    ],
    "after": [
      "D-4yyj7v",
      "D-wnrxww"
    ],
    "resolution": {
      "chosen": [
        "book-author",
        "orderitem-book"
      ],
      "note": "demo answer",
      "by": "user",
      "at": "2026-10-21"
    }
  }
}

== decisions/D-qbc6qk-federation-entities.json
{
  "contract_version": 2,
  "decision": {
    "id": "D-qbc6qk",
    "slug": "federation-entities",
    "title": "Federation entities",
    "status": "resolved",
    "date": "2026-10-21",
    "phase": "design",
    "question": "Which types should be federation entities (@key(fields: \"id\")) that another subgraph can reference or extend? Types in scope with a by-id lookup: Book, Author, Customer, Order, Integration.",
    "context": "Recommendation: catalog. Another subgraph can then reference or extend Book and Author; each entity needs its by-id lookup connector (GET /books/{bookId}, GET /authors/{authorId}), which is in scope. Exposing Customer or Integration as entities widens who can reach personal data and credentials.",
    "affects": [
      "lumen-books.graphql"
    ],
    "choices": [
      {
        "id": "none",
        "label": "None: root fields and relationship links only"
      },
      {
        "id": "catalog",
        "label": "Catalog types: Book and Author keyed by id"
      },
      {
        "id": "all",
        "label": "All five: Book, Author, Customer, Order, Integration keyed by id"
      }
    ],
    "resolution": {
      "chosen": [
        "catalog"
      ],
      "note": "demo answer",
      "by": "user",
      "at": "2026-10-21"
    }
  }
}

