{
 "openapi": "3.0.3",
 "info": {
  "title": "Lumen Books API",
  "version": "1.0.0",
  "description": "A small bookshop REST API used to demo Forgeline's GraphOS mode."
 },
 "servers": [
  {
   "url": "http://127.0.0.1:4010"
  }
 ],
 "security": [
  {
   "bearerAuth": []
  }
 ],
 "tags": [
  {
   "name": "Catalog"
  },
  {
   "name": "Customers"
  },
  {
   "name": "Orders"
  },
  {
   "name": "Integrations"
  }
 ],
 "paths": {
  "/books": {
   "get": {
    "operationId": "listBooks",
    "tags": [
     "Catalog"
    ],
    "summary": "List books",
    "description": "Page-number pagination. `ids` fetches several books in one call.",
    "parameters": [
     {
      "name": "page",
      "in": "query",
      "required": false,
      "description": "Page number, from 1.",
      "schema": {
       "type": "integer",
       "minimum": 1,
       "default": 1
      }
     },
     {
      "name": "limit",
      "in": "query",
      "required": false,
      "description": "Page size.",
      "schema": {
       "type": "integer",
       "minimum": 1,
       "maximum": 50,
       "default": 10
      }
     },
     {
      "name": "genre",
      "in": "query",
      "required": false,
      "description": "Only books in this genre.",
      "schema": {
       "type": "string"
      }
     },
     {
      "name": "ids",
      "in": "query",
      "required": false,
      "description": "Comma-separated book ids. If not passed, all books are listed.",
      "schema": {
       "type": "string"
      }
     }
    ],
    "responses": {
     "200": {
      "description": "OK",
      "content": {
       "application/json": {
        "schema": {
         "$ref": "#/components/schemas/BookPage"
        }
       }
      }
     },
     "401": {
      "description": "Error",
      "content": {
       "application/json": {
        "schema": {
         "$ref": "#/components/schemas/Error"
        }
       }
      }
     }
    }
   }
  },
  "/books/{bookId}": {
   "get": {
    "operationId": "getBook",
    "tags": [
     "Catalog"
    ],
    "summary": "Get one book",
    "parameters": [
     {
      "name": "bookId",
      "in": "path",
      "required": true,
      "description": "Book id.",
      "schema": {
       "type": "string"
      }
     }
    ],
    "responses": {
     "200": {
      "description": "OK",
      "content": {
       "application/json": {
        "schema": {
         "$ref": "#/components/schemas/Book"
        }
       }
      }
     },
     "404": {
      "description": "Error",
      "content": {
       "application/json": {
        "schema": {
         "$ref": "#/components/schemas/Error"
        }
       }
      }
     }
    }
   }
  },
  "/books/search": {
   "post": {
    "operationId": "searchBooks",
    "tags": [
     "Catalog"
    ],
    "summary": "Search books",
    "description": "A POST that only reads. The GraphOS select step asks whether it is a query.",
    "requestBody": {
     "required": true,
     "content": {
      "application/json": {
       "schema": {
        "$ref": "#/components/schemas/BookSearch"
       }
      }
     }
    },
    "responses": {
     "200": {
      "description": "OK",
      "content": {
       "application/json": {
        "schema": {
         "$ref": "#/components/schemas/BookPage"
        }
       }
      }
     },
     "422": {
      "description": "Error",
      "content": {
       "application/json": {
        "schema": {
         "$ref": "#/components/schemas/Error"
        }
       }
      }
     }
    }
   }
  },
  "/authors/{authorId}": {
   "get": {
    "operationId": "getAuthor",
    "tags": [
     "Catalog"
    ],
    "summary": "Get one author",
    "parameters": [
     {
      "name": "authorId",
      "in": "path",
      "required": true,
      "description": "Author id.",
      "schema": {
       "type": "string"
      }
     }
    ],
    "responses": {
     "200": {
      "description": "OK",
      "content": {
       "application/json": {
        "schema": {
         "$ref": "#/components/schemas/Author"
        }
       }
      }
     },
     "404": {
      "description": "Error",
      "content": {
       "application/json": {
        "schema": {
         "$ref": "#/components/schemas/Error"
        }
       }
      }
     }
    }
   }
  },
  "/customers/{customerId}": {
   "get": {
    "operationId": "getCustomer",
    "tags": [
     "Customers"
    ],
    "summary": "Get one customer",
    "description": "Returns personal data (email, phone). Whether to expose it is a design decision.",
    "parameters": [
     {
      "name": "customerId",
      "in": "path",
      "required": true,
      "description": "Customer id.",
      "schema": {
       "type": "string"
      }
     }
    ],
    "responses": {
     "200": {
      "description": "OK",
