    "status": "resolved",
    "date": "2026-10-21",
    "after": [
      "D-a39c6a"
    ],
    "question": "Order.payment is a card or a bank account. Map it inline as one typed object (type, last4, brand, iban), or as a union that a field-level connector re-fetches through GET /orders/{orderId}?",
    "affects": [
      "Lumen_Books_Order.payment"
    ],
    "choices": [
      {
        "id": "object",
        "label": "one object type Lumen_Books_Payment {type, last4, brand, iban}, mapped inline by every Order connector"
      },
      {
        "id": "union",
        "label": "union Lumen_Books_CardPayment | Lumen_Books_BankPayment on a field-level connector, one extra GET /orders/{orderId} per order"
      }
